SELECT ?producer ?producerLabelEn ?producerLabelRu ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start ?gold_count_estimate WHERE {
      {
        SELECT ?producer ?producerLabelEn ?producerLabelRu ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        ?item wdt:P31 wd:Q169930 .
        ?item wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?item wdt:P162 ?producer .
        ?item wdt:P264 ?label .
        ?item wdt:P136 ?genre .
        ?producer rdfs:label ?producerLabelEn FILTER(LANG(?producerLabelEn) = "en") .
        OPTIONAL { ?producer rdfs:label ?producerLabelRu FILTER(LANG(?producerLabelRu) = "ru") . }
        ?label rdfs:label ?labelLabelEn FILTER(LANG(?labelLabelEn) = "en") .
        OPTIONAL { ?label rdfs:label ?labelLabelRu FILTER(LANG(?labelLabelRu) = "ru") . }
        ?genre rdfs:label ?genreLabelEn FILTER(LANG(?genreLabelEn) = "en") .
        OPTIONAL { ?genre rdfs:label ?genreLabelRu FILTER(LANG(?genreLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 10) * 10 + 1950) AS ?period_start) .
        }
        GROUP BY ?producer ?producerLabelEn ?producerLabelRu ?label ?labelLabelEn ?labelLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800

